{
  "missing_information": [
    {
      "category": "Tool Selection Criteria",
      "gap": "No information on how or why a specific tool is chosen for a given wafer measurement",
      "why_it_matters": "Without knowing the selection logic, it is impossible to model the branching condition that routes a wafer to one tool versus another, which is essential for accurate process reconstruction and automation"
    },
    {
      "category": "Preparation Steps per Tool",
      "gap": "The specific preparation actions required before measurement for each tool are not described",
      "why_it_matters": "Preparation steps may vary significantly by tool and could include manual handling, calibration, or environmental conditioning; omitting them creates gaps in the workflow model and missed automation candidates"
    },
    {
      "category": "Measurement Step Details",
      "gap": "The individual measurement actions, their sequence, and any decision points within each tool's measurement procedure are unspecified",
      "why_it_matters": "Without step-level detail, it is not possible to identify which sub-steps are automatable, error-prone, or time-consuming"
    },
    {
      "category": "Result Recording Method",
      "gap": "It is unclear how the engineer records the result — whether manually, via a system interface, or through automated data capture — and where the data is stored",
      "why_it_matters": "The recording method directly affects automation potential and data quality; a manual entry step is a common bottleneck and error source"
    },
    {
      "category": "Exception and Rework Handling",
      "gap": "No information is provided about what happens when a measurement fails, produces an out-of-spec result, or a tool becomes unavailable",
      "why_it_matters": "Exception paths are critical for a complete workflow model and often represent the highest-impact areas for process improvement"
    },
    {
      "category": "Handoff and Triggering Events",
      "gap": "It is unclear what triggers the start of the measurement workflow (e.g., a work order, a prior process step completion, or a manual request) and who hands off the wafer to the measurement engineer",
      "why_it_matters": "Without knowing the triggering event and handoff mechanism, the process boundaries cannot be defined and integration points for automation cannot be identified"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What criteria or rules determine which tool is selected for measuring a particular wafer — for example, is the choice based on wafer type, measurement parameter, tool availability, or engineer judgment?",
      "targets": ["Tool Selection Criteria"]
    },
    {
      "id": "Q2",
      "question": "For each tool used in this workflow, what are the specific preparation steps that must be completed before the actual measurement begins?",
      "targets": ["Preparation Steps per Tool"]
    },
    {
      "id": "Q3",
      "question": "Can you walk through the individual actions an engineer performs during the measurement step for each tool, including any intermediate checks or decisions made during the measurement?",
      "targets": ["Measurement Step Details"]
    },
    {
      "id": "Q4",
      "question": "How does the engineer record the measurement result — is it entered manually into a form or system, automatically captured from the tool, or some combination — and what system or medium holds the final recorded data?",
      "targets": ["Result Recording Method"]
    },
    {
      "id": "Q5",
      "question": "What happens when a measurement result is out of specification or when the measurement cannot be completed — is the wafer re-measured, re-routed, or escalated, and who makes that decision?",
      "targets": ["Exception and Rework Handling"]
    },
    {
      "id": "Q6",
      "question": "What event or condition triggers the start of this measurement workflow, and who or what is responsible for delivering the wafer to the measurement engineer?",
      "targets": ["Handoff and Triggering Events"]
    }
  ]
}
